const state={lesson:0,step:0,playing:false,timer:null,view:'memory',completed:new Set()};
const $=id=>document.getElementById(id);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function highlightCode(line){let s=escapeHtml(line),tokens=[];s=s.replace(/(&quot;.*?&quot;|\/\/.*$)/g,m=>{const key=`¤${String.fromCharCode(65+tokens.length)}¤`;tokens.push({key,value:m.startsWith('//')?`<span class="comment">${m}</span>`:`<span class="str">${m}</span>`});return key});s=s.replace(/\b(public|private|class|static|void|for|int|String|new|return|this)\b/g,'<span class="kw">$1</span>').replace(/\b(System|Main|App|Student)\b/g,'<span class="type">$1</span>').replace(/\b(println|length|main|getName|getScore|setScore)\b/g,'<span class="method">$1</span>').replace(/\b(\d+)\b/g,'<span class="num">$1</span>');tokens.forEach(t=>s=s.replace(t.key,t.value));return s}

function renderNav(){const nav=$('lessonNav');nav.innerHTML=lessons.map((l,i)=>`<button class="lesson-button ${i===state.lesson?'active':''} ${state.completed.has(i)?'complete':''}" data-lesson="${i}"><span class="lesson-index">${i+1}</span><span class="lesson-info"><strong>${l.title}</strong><span>${l.subtitle}</span></span><span class="status-mark">${state.completed.has(i)?'✓':'›'}</span></button>`).join('');nav.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>selectLesson(Number(b.dataset.lesson))));$('completedCount').textContent=`${state.completed.size}/${lessons.length}`}
function renderCode(){const lesson=lessons[state.lesson],step=lesson.steps[state.step],file=step.file||'Main.java',code=lesson.files?.[file]||lesson.code;$('fileName').textContent=file;$('codeArea').innerHTML=code.map((line,i)=>`<div class="code-line ${i+1===step.line?'active':''}"><span class="line-number">${i+1}</span><span class="exec-arrow">▶</span><code>${highlightCode(line)}</code></div>`).join('');document.querySelector('.code-line.active')?.scrollIntoView({block:'nearest'})}
function varsHtml(step){const entries=Object.entries(step.vars||{});return entries.length?`<div class="variable-grid">${entries.map(([k,v])=>`<div class="var-card"><div class="var-type">${escapeHtml(step.types?.[k]||'reference')}</div><div class="var-row"><span>${escapeHtml(k)}</span><span class="var-value">${escapeHtml(v)}</span></div></div>`).join('')}</div>`:'<p class="console-empty">No local variables yet.</p>'}
function arrayHtml(step){if(step.matrix){const cols=step.matrix[0].length;return `<div class="array-wrap"><div class="array-title">grid <span class="var-type">int[][]</span></div><div class="matrix" style="grid-template-columns:repeat(${cols},48px)">${step.matrix.flatMap((row,r)=>row.map((v,c)=>`<div class="array-cell ${step.activeCell?.[0]===r&&step.activeCell?.[1]===c?'active':''}"><span class="cell-index">[${r}][${c}]</span>${v}</div>`)).join('')}</div></div>`}if(step.array){return `<div class="array-wrap"><div class="array-title">array memory</div><div class="array-cells">${step.array.map((v,i)=>`<div class="array-cell ${step.activeCell===i?'active':''}"><span class="cell-index">${i}</span>${v}</div>`).join('')}</div></div>`}return ''}
